 nr=1+sum(1 for r in g[1:-1] if r[0]==sep and r[-1]==sep and len(set(r))==1)
 nc=1+sum(1 for j in range(1,len(g[0])-1) if g[0][j]==sep and g[-1][j]==sep and len({r[j] for r in g[1:-1]})==1)
 h=(len(g)-nr-1)//nr;w=(len(g[0])-nc-1)//nc
 ts=[]
 for br in range(nr):
  row=[]
  for bc in range(nc):
   r=1+br*(h+1);c=1+bc*(w+1);row.append([rr[c:c+w] for rr in g[r:r+h]])
  ts.append(row)
 return ts,sep
