    match=(X==T[j]);lp[:,j]=np.log(w[j]+1e-20)+(match*np.log((1-p0 if False else 1)/1)).sum(1) # overwrite
    lp[:,j]=np.log(w[j]+1e-20)+(X*np.where(T[j],np.log(p1/p0),0)+ (1-X)*np.where(T[j],np.log((1-p1)/(1-p0)),0)).sum(1)+d*np.log(1-p0)+T[j].sum()*np.log(p0/(1-p0))
